const cfg = $('Set digest options').first().json;

function asText(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function parseGrantDate(raw) {
  const text = asText(raw);
  if (!text) return null;
  let match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (match) {
    return new Date(Number(match[3]), Number(match[1]) - 1, Number(match[2]));
  }
  match = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (match) {
    return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  }
  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function startOfToday() {
  const now = new Date();
  return new Date(now.getFullYear(), now.getMonth(), now.getDate());
}

function daysUntil(date) {
  if (!date) return null;
  const start = startOfToday();
  const close = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  return Math.round((close.getTime() - start.getTime()) / 86400000);
}

function escapeHtml(value) {
  return asText(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function grantKey(row) {
  return asText(row.number || row.opportunityNumber || row.id || row.opportunityId || row.title);
}

function collectRows(items) {
  const rows = [];
  const pushValue = (value) => {
    if (value === undefined || value === null) return;
    if (Array.isArray(value)) {
      value.forEach(pushValue);
      return;
    }
    if (typeof value === 'object') {
      const keys = Object.keys(value);
      const numericKeys = keys.length > 0 && keys.every((key) => /^\d+$/.test(key));
      if (numericKeys) {
        keys.sort((a, b) => Number(a) - Number(b)).forEach((key) => pushValue(value[key]));
        return;
      }
      if (Array.isArray(value.data)) {
        pushValue(value.data);
        return;
      }
      if (Array.isArray(value.items)) {
        pushValue(value.items);
        return;
      }
      if (Array.isArray(value.body)) {
        pushValue(value.body);
        return;
      }
      rows.push(value);
      return;
    }
  };
  items.forEach((item) => pushValue(item.json));
  return rows;
}

const rawRows = collectRows($input.all());
const closingSoonDays = Number(cfg.closingSoonDays);
const maxGrantsInEmail = Number(cfg.maxGrantsInEmail) || 25;
const dedupeMemoryDays = Number(cfg.dedupeMemoryDays) || 90;
const today = startOfToday();
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentGrantKeys || typeof staticData.sentGrantKeys !== 'object') {
  staticData.sentGrantKeys = {};
}

const cutoff = today.getTime() - dedupeMemoryDays * 86400000;
for (const [key, sentAt] of Object.entries(staticData.sentGrantKeys)) {
  const sentTime = Date.parse(sentAt);
  if (!sentTime || sentTime < cutoff) {
    delete staticData.sentGrantKeys[key];
  }
}

const seenThisRun = new Set();
const grants = [];
let skippedDedupe = 0;
let skippedInvalid = 0;

for (const row of rawRows) {
  const title = asText(row.title || row.opportunityTitle);
  const number = asText(row.number || row.opportunityNumber);
  const id = asText(row.id || row.opportunityId);
  const key = grantKey(row);
  if (!title && !number && !id) {
    skippedInvalid += 1;
    continue;
  }
  if (!key) {
    skippedInvalid += 1;
    continue;
  }
  if (seenThisRun.has(key)) continue;
  seenThisRun.add(key);
  if (staticData.sentGrantKeys[key]) {
    skippedDedupe += 1;
    continue;
  }
  const closeDate = parseGrantDate(row.closeDate || row.close_date);
  const openDate = parseGrantDate(row.openDate || row.open_date);
  const daysToClose = daysUntil(closeDate);
  const closingSoon = daysToClose !== null && daysToClose >= 0 && daysToClose <= closingSoonDays;
  grants.push({
    id,
    number,
    title,
    agency: asText(row.agency || row.agencyName),
    agencyCode: asText(row.agencyCode),
    openDate: asText(row.openDate || row.open_date),
    closeDate: asText(row.closeDate || row.close_date),
    oppStatus: asText(row.oppStatus || row.status),
    docType: asText(row.docType),
    cfdaList: asText(row.cfdaList),
    url: asText(row.url) || (id ? `https://www.grants.gov/search-results-detail/${id}` : ''),
    daysToClose,
    closingSoon,
    openDateValue: openDate ? openDate.getTime() : null,
    closeDateValue: closeDate ? closeDate.getTime() : Number.POSITIVE_INFINITY,
  });
}

grants.sort((a, b) => {
  if (a.closeDateValue !== b.closeDateValue) return a.closeDateValue - b.closeDateValue;
  const openA = a.openDateValue == null ? Number.POSITIVE_INFINITY : a.openDateValue;
  const openB = b.openDateValue == null ? Number.POSITIVE_INFINITY : b.openDateValue;
  if (openA !== openB) return openA - openB;
  return asText(a.title).localeCompare(asText(b.title));
});

const listed = grants.slice(0, maxGrantsInEmail);
const hiddenCount = grants.length - listed.length;
const closingSoonCount = grants.filter((grant) => grant.closingSoon).length;
const keywordLabel = asText(cfg.keyword) || 'all keywords';
const agencyLabel = asText(cfg.agency) || 'all agencies';
const subject = grants.length
  ? `Grants.gov digest: ${grants.length} new opportunit${grants.length === 1 ? 'y' : 'ies'} (${keywordLabel})`
  : 'Grants.gov digest: no new opportunities';

const rowsHtml = listed.map((grant) => {
  const closeLabel = grant.closeDate || 'No close date';
  const daysLabel = grant.daysToClose === null
    ? ''
    : grant.daysToClose < 0
      ? ' (closed)'
      : grant.daysToClose === 0
        ? ' (closes today)'
        : ` (${grant.daysToClose} day${grant.daysToClose === 1 ? '' : 's'} left)`;
  const soonBadge = grant.closingSoon ? ' <strong>Closing soon</strong>' : '';
  const link = grant.url
    ? `<a href="${escapeHtml(grant.url)}">${escapeHtml(grant.number || grant.id || 'View on Grants.gov')}</a>`
    : escapeHtml(grant.number || grant.id || '');
  return `<tr>
  <td style="padding:8px;border-bottom:1px solid #ddd;vertical-align:top;">${link}${soonBadge}</td>
  <td style="padding:8px;border-bottom:1px solid #ddd;vertical-align:top;">${escapeHtml(grant.title)}</td>
  <td style="padding:8px;border-bottom:1px solid #ddd;vertical-align:top;">${escapeHtml(grant.agency)}</td>
  <td style="padding:8px;border-bottom:1px solid #ddd;vertical-align:top;white-space:nowrap;">${escapeHtml(closeLabel)}${daysLabel}</td>
</tr>`;
}).join('\n');

const html = grants.length
  ? `<p>New or still-unseen federal grant opportunities from Grants.gov for <strong>${escapeHtml(keywordLabel)}</strong> / <strong>${escapeHtml(agencyLabel)}</strong>.</p>
<p>${grants.length} listed below${closingSoonCount ? `, including ${closingSoonCount} closing within ${closingSoonDays} days` : ''}${hiddenCount ? `. Showing the first ${listed.length}; ${hiddenCount} more were ranked but omitted from this email` : ''}.</p>
<table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:14px;">
  <thead>
    <tr>
      <th style="text-align:left;padding:8px;border-bottom:2px solid #333;">Opportunity</th>
      <th style="text-align:left;padding:8px;border-bottom:2px solid #333;">Title</th>
      <th style="text-align:left;padding:8px;border-bottom:2px solid #333;">Agency</th>
      <th style="text-align:left;padding:8px;border-bottom:2px solid #333;">Close date</th>
    </tr>
  </thead>
  <tbody>
    ${rowsHtml}
  </tbody>
</table>
<p style="color:#555;font-size:12px;">Source: Grants.gov via the publicrecords/grants-gov-scraper Actor on your Apify account. Already emailed opportunities are skipped until dedupe memory expires.</p>`
  : '<p>No new Grants.gov opportunities remained after filters and dedupe.</p>';

const text = grants.length
  ? listed.map((grant) => {
      const closeLabel = grant.closeDate || 'No close date';
      return `- ${grant.number || grant.id || ''} | ${grant.title} | ${grant.agency} | Closes ${closeLabel} | ${grant.url}`;
    }).join('\n')
  : 'No new Grants.gov opportunities remained after filters and dedupe.';

if (grants.length) {
  const sentAt = new Date().toISOString();
  for (const grant of grants) {
    const key = grant.number || grant.id || grant.title;
    staticData.sentGrantKeys[key] = sentAt;
  }
}

const cleanGrants = grants.map((grant) => {
  const copy = { ...grant };
  delete copy.openDateValue;
  delete copy.closeDateValue;
  return copy;
});

return [{
  json: {
    count: grants.length,
    listedCount: listed.length,
    hiddenCount,
    closingSoonCount,
    skippedDedupe,
    skippedInvalid,
    subject,
    html,
    text,
    grants: cleanGrants,
    digestEmail: asText(cfg.digestEmail),
  },
}];

const cfg = $('Set digest options').first().json;
const payload = $input.first().json || {};
const err = payload.error || payload;
const status = err.httpCode || err.statusCode || payload.statusCode || payload.status || 'unknown';
const message = err.message || payload.message || JSON.stringify(payload);
const digestEmail = String(cfg.digestEmail || '');
const subject = 'Grants.gov digest failed';
const html = `<p>The Grants.gov fetch failed, so no digest was sent.</p>
<p><strong>Status:</strong> ${status}</p>
<p><strong>Message:</strong> ${String(message).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</p>
<p>Check your Apify Header Auth credential, Actor input, and the Actor run log in your Apify Console. This workflow did not include any API token in its parameters.</p>`;
return [{ json: { subject, html, digestEmail, status, message: String(message) } }];
